function updatePlay(){ $('#play').textContent=playing?'Ⅱ 暂停':'▶ 播放';$('#run-status').textContent=playing?'演示运行中':'演示已暂停';}
$('#play').onclick=()=>{playing=!playing;updatePlay();};$('#reset').onclick=()=>{totalTime=0;lastVisionKey='';drawState();};$('#step').onclick=()=>{playing=false;updatePlay();const {c,s}=stageInfo();totalTime=c*cycle+starts[s+1]+.0001;drawState();};$('#speed').onchange=e=>speed=+e.target.value;
$$('[data-stage]').forEach(b=>b.onclick=()=>{const {c}=stageInfo();totalTime=c*cycle+starts[+b.dataset.stage];playing=false;updatePlay();drawState();});$$('[data-device]').forEach(b=>b.onclick=()=>select(b.dataset.device));
function setView(type){const positions={overview:[10,9,12],top:[.3,15,.1],close:[-5.5,5,5.5]};viewCamera.position.set(...positions[type]);controls.target.set(...(type==='close'?[-2.2,1.8,0]:[.5,.7,0]));controls.update();$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===type));}$$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#reset-view').onclick=()=>setView('overview');
function modal(html){$('#modal-content').innerHTML=html;$('#modal').showModal();}$('.close').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#help').onclick=()=>modal('<div class="eyebrow">QUICK START</div><h2>亲手探索这条物流线</h2><ol><li>拖动场景旋转，滚轮或双指缩放。</li><li>点击设备模型、浮动标签或右侧设备按钮查看详情。</li><li>选中相机，调节安装高度和货垛高度，观察视野变化。</li><li>打开模拟点云，理解相机如何感知箱体表面。</li><li>点击底部任一步骤跳转；用单步、暂停和倍速控制演示。</li></ol><p>场景以每次搬运一箱演示设备协作，八箱完成后进入下一托盘循环。</p>');
$('#sources').onclick=()=>modal('<div class="eyebrow">REFERENCE & ASSUMPTIONS</div><h2>参数与场景依据</h2><p>相机参考 Mech-Eye DEEP 技术文档：推荐距离 1.2–3.5 m；视野 1.2 × 1.0 m @ 1.2 m、3.5 × 2.8 m @ 3.5 m；深度图 2048 × 1536；典型采集时间 0.5–0.9 s。</p><p>动态视野按上述两个端点做线性近似，超范围时显示外推提示。正式应用应使用对应型号的官方 FOV 计算器和实际标定。点云是合成数据，未接入相机。</p><p>模型尺寸、动作时长和物流路线均为演示设定。机器人为简化运动学模型。</p><p><a href="https://docs.mech-mind.net/en/eye-3d-camera/2.2.1/hardware/specifications-deep.html" target="_blank" rel="noopener">Mech-Eye DEEP 技术规格 ↗</a><br><a href="https://resources.mech-mind.com.cn/fov_calculator/?model=DEEP" target="_blank" rel="noopener">官方 FOV 计算器 ↗</a><br><a href="https://www.mech-mind.com/cases/ai-3d-vision-guided-case-depalletizing-and-palletizing.html" target="_blank" rel="noopener">梅卡曼德拆码垛案例 ↗</a></p>');
function resize(){const w=viewport.clientWidth,h=viewport.clientHeight;renderer.setSize(w,h);viewCamera.aspect=w/h;viewCamera.updateProjectionMatrix();}new ResizeObserver(resize).observe(viewport);setView('overview');select('camera');resize();$('#loading').remove();
let last;function frame(now){const dt=last===undefined?0:Math.max(0,Math.min((now-last)/1000,.08));last=now;if(playing)totalTime+=dt*speed;controls.update();drawState();renderer.render(scene,viewCamera);requestAnimationFrame(frame);}requestAnimationFrame(frame);
